   * global 256-char cap (UI uses `maxLength` for the input's own limit).
   */
  maxLength?: number;
  /**
   * string fields only. Regex SOURCE (compiled with the `u` flag, tested
   * against the whole value) the value must match — data, not a function, so
   * the schema stays serialisable into the client settings form.
   */
  pattern?: string;
  /** Shown when `pattern`/length rules reject a value. */
  patternError?: string;
};

/**
 * Per-field string rules (length + pattern), shared by `validateConfig`
 * (server) and the settings form (client) so both say the same thing.
 * Returns an error message or null. Blank values on a non-required field are
 * not rule-checked (blank means "unset").
 */
export function stringFieldError(field: ConfigField, v: string): string | null {
  if (field.type !== "string") return null;
  if (v.trim().length === 0) return null;
  if (field.minLength != null && v.length < field.minLength) {
    return `${field.label} must be at least ${field.minLength} characters.`;
  }
  if (field.maxLength != null && v.length > field.maxLength) {
    return `${field.label} is too long (max ${field.maxLength} characters).`;
  }
  if (field.pattern) {
    let re: RegExp | null = null;
    try {
      re = new RegExp(field.pattern, "u");
    } catch {
      re = null;
    }
    if (re && !re.test(v)) return field.patternError ?? `${field.label} contains characters that are not allowed.`;
  }
  return null;
}

