import type { Guest } from "../types";
import { shq } from "../types";

/**
 * Stop-edit-start strategy, for games that RE-WRITE their own config files while
 * running or on shutdown (Project Zomboid's servertest.ini, Sons of the Forest's
 * dedicatedserver.cfg, Don't Starve Together's cluster.ini): an edit made under a
 * running server can be silently overwritten, so the game is stopped first.
 *
 *   is-active? -> stop the unit -> run `edit` (your config-file patches) ->
 *   start the unit (only if it was running) -> wait for the port
 *
 * If `edit` fails, or the game does not come back, `undo` is called (put the files
 * back), then the game is started again if it was running. A server the customer had
 * stopped is edited but NOT started. With no systemd `unit` the edit is NOT done
 * under a stop (we cannot stop it safely): `skipped` comes back and the caller falls
 * back to a plain write + "restart needed".
 */
export type StoppedEditResult =
  | { status: "skipped" }
  | { status: "done"; wasActive: boolean; notes: string[]; value: unknown }
  | { status: "failed"; note: string };

export async function withGameStopped<T>(
  guest: Guest,
  o: {
    unit: string | null;
    container: string;
    waitPort(): Promise<{ ok: boolean } | null>;
    /** Runs with the game stopped. Return `{ ok:false, note }` to abort (nothing may be left half-written). */
    edit(): Promise<{ ok: true; value: T } | { ok: false; note: string }>;
    /** Put files back after a failed start. */
    undo(): Promise<void>;
  },
): Promise<StoppedEditResult> {
  const { unit, container } = o;
  if (!unit || !/^[A-Za-z0-9_.@-]+\.service$/.test(unit) && !/^[A-Za-z0-9_.@-]+$/.test(unit)) return { status: "skipped" };
  const wasActive = (await guest.exec(`systemctl is-active ${shq(unit)}`)).stdout.trim() === "active";
  const start = () => guest.exec(`systemctl start ${shq(unit)}`, 120_000);
  const running = async () => (await guest.exec(`docker inspect -f '{{.State.Running}}' ${shq(container)} 2>/dev/null`)).stdout.trim() === "true";

  if (wasActive) {
    const st = await guest.exec(`systemctl stop ${shq(unit)}`, 120_000);
    if (st.code !== 0 || (await running())) {
      await start().catch(() => undefined);
      return { status: "failed", note: "Could not stop the game cleanly, so nothing was changed." };
    }
  }

  let res: { ok: true; value: T } | { ok: false; note: string };
  try {
    res = await o.edit();
  } catch (e) {
    res = { ok: false, note: `The edit failed (${(e as Error).message.slice(0, 100)}).` };
  }
  if (!res.ok) {
    await o.undo().catch(() => undefined);
    if (wasActive) await start().catch(() => undefined);
    return { status: "failed", note: res.note };
  }

  const notes: string[] = [];
  if (wasActive) {
    const s = await start();
    if (s.code !== 0) {
      await o.undo().catch(() => undefined);
      await guest.exec(`systemctl stop ${shq(unit)}`, 120_000).catch(() => undefined);
      const back = await start().catch(() => null);
      return { status: "failed", note: `The game did not start with the new settings. Your previous settings were put back${back && back.code === 0 ? "" : ", but the game could not be started again — support has been alerted"}.` };
    }
    const port = await o.waitPort();
    if (!(await running())) {
      await o.undo().catch(() => undefined);
      await guest.exec(`systemctl stop ${shq(unit)}`, 120_000).catch(() => undefined);
      await start().catch(() => undefined);
      return { status: "failed", note: "The game did not come back up with the new settings, so your previous settings were put back." };
    }
    if (port && !port.ok) notes.push("The game is running but wasn't answering yet when we checked — it may still be loading.");
  }
  return { status: "done", wasActive, notes, value: res.value };
}

