 *    therefore changed by recreating the container with new env (volumes untouched).
 *  - PublicName / PVP / PauseEmpty are plain ini keys the image never touches, and Zombies /
 *    Speed are SandboxVars.lua keys. PZ re-serialises these files itself, so they are edited
 *    with the game STOPPED (stop-edit-start), never under a running server.
 *  - ADMIN_PASSWORD: the account's bcrypt hash lives in the sqlite db, handled by
 *    worker/zomboid-admin.ts (unchanged; the applier calls it).
 *  - ADMIN_USERNAME is deliberately not applied to a running server (renaming the account row
 *    would orphan its characters/permissions; unverified). It still applies on a fresh install.
 */

export const PZ_NOTE_RESTART = "Applies on save: your server restarts briefly (players are disconnected).";

export const PROJECTZOMBOID_SPEC: GameConfigApplierSpec = {
  family: "projectzomboid",
  fields: {
    PublicName: { when: "recreate", note: PZ_NOTE_RESTART },
    PVP: { when: "recreate", note: PZ_NOTE_RESTART },
    PauseEmpty: { when: "recreate", note: PZ_NOTE_RESTART },
    Zombies: { when: "recreate", note: `${PZ_NOTE_RESTART} Population changes show up as areas load and zombies respawn, not instantly.` },
    Speed: { when: "recreate", note: PZ_NOTE_RESTART },
    MaxPlayers: { when: "recreate", note: "Applies on save: the container is rebuilt with the new limit (the image re-applies it from its settings at every start). Brief restart." },
    RCON_PASSWORD: { when: "recreate", secret: true, note: "Applies on save: the container is rebuilt with the new RCON password. Brief restart." },
    MEMORY_XMX_GB: { when: "recreate", note: "Applies on save: the container is rebuilt with the new Java heap. Brief restart." },
    ADMIN_PASSWORD: { when: "recreate", secret: true, note: "Applies on save: your server restarts for about a minute and the new password is checked before we say it worked." },
  },
};

export const PZ_CONTAINER = "projectzomboid";
export const PZ_CONFIG_ROOT = "/opt/projectzomboid/config";
export const PZ_ENV_FILE = "/root/projectzomboid.env";

/** Fields written into `<name>.ini`. */
export const PZ_INI_FIELDS = ["PublicName", "PVP", "PauseEmpty"] as const;
/** Fields written into `<name>_SandboxVars.lua`. */
export const PZ_SANDBOX_FIELDS = ["Zombies", "Speed"] as const;
/** schema field -> docker env var (container recreate). */
export const PZ_ENV_FIELDS: Record<string, string> = { MaxPlayers: "MAX_PLAYERS", RCON_PASSWORD: "RCON_PASSWORD", MEMORY_XMX_GB: "MEMORY_XMX_GB" };

type V = Record<string, string | number | boolean | undefined>;

export function pzIniEdits(values: V, only: readonly string[]): { key: string; value: string }[] {
  const out: { key: string; value: string }[] = [];
  if (only.includes("PublicName")) out.push({ key: "PublicName", value: String(values.PublicName ?? "").replace(/[\r\n]/g, " ").trim() });
  if (only.includes("PVP")) out.push({ key: "PVP", value: values.PVP === true ? "true" : "false" });
  if (only.includes("PauseEmpty")) out.push({ key: "PauseEmpty", value: values.PauseEmpty === true ? "true" : "false" });
  return out;
}

export function pzEnvChanges(values: V, only: readonly string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [field, env] of Object.entries(PZ_ENV_FIELDS)) {
    if (!only.includes(field)) continue;
    out[env] = String(values[field] ?? "").replace(/[\r\n]/g, " ");
  }
  return out;
}

/**
 * Zombie Population. The schema offers Build 42's six steps (1 Insane, 2 Very High, 3 High,
 * 4 Normal, 5 Low, 6 None). Build 41's file has five (1 Insane, 2 High, 3 Normal, 4 Low,
 * 5 None). The file's own `VERSION` says which one a server is on (>= 6: Build 42 layout).
 */
export function pzZombiesForFile(schemaValue: number, fileVersion: number): number {
  if (fileVersion >= 6) return schemaValue;
  return [1, 2, 2, 3, 4, 5][Math.min(Math.max(schemaValue, 1), 6) - 1];
}

// ---- SandboxVars.lua (tiny, brace-aware patcher; no Lua interpreter) -----------------

const OPEN = /^(\s*)SandboxVars\s*=\s*\{[ \t]*$/m;

export function readSandboxVersion(lua: string): number | null {
  const m = /^\s*VERSION\s*=\s*(\d+)/m.exec(lua);
  return m ? Number(m[1]) : null;
}

/** Top-level `Zombies = n` (not ZombieLore, not nested keys that merely start with Zombies). */
export function readSandboxZombies(lua: string): number | undefined {
  const m = /^\s*Zombies\s*=\s*(\d+)/m.exec(lua);
  return m ? Number(m[1]) : undefined;
}

function zombieLoreRange(lua: string): { start: number; end: number } | null {
  const m = /^(\s*)ZombieLore\s*=\s*\{/m.exec(lua);
  if (!m) return null;
  const start = m.index + m[0].length;
  let depth = 1;
  for (let i = start; i < lua.length; i++) {
    if (lua[i] === "{") depth++;
    else if (lua[i] === "}" && --depth === 0) return { start, end: i };
  }
  return null;
}

export function readSandboxSpeed(lua: string): number | undefined {
  const r = zombieLoreRange(lua);
  if (!r) return undefined;
  const m = /^\s*Speed\s*=\s*(\d+)/m.exec(lua.slice(r.start, r.end));
  return m ? Number(m[1]) : undefined;
}

/** Sets Zombies and/or Speed; preserves everything else. Throws if the file has no `SandboxVars = {`. */
export function patchSandboxLua(lua: string, edits: { Zombies?: number; Speed?: number }): string {
  const eol = lua.includes("\r\n") ? "\r\n" : "\n";
  let out = lua;
  const open = OPEN.exec(out);
  if (!open) throw new Error("no SandboxVars table");
  const afterOpen = () => OPEN.exec(out)!.index + OPEN.exec(out)![0].length;
  if (edits.Zombies !== undefined) {
    if (/^\s*Zombies\s*=\s*\d+/m.test(out)) out = out.replace(/^(\s*Zombies\s*=\s*)\d+/m, (_m, p) => `${p}${edits.Zombies}`);
    else out = out.slice(0, afterOpen()) + `${eol}    Zombies = ${edits.Zombies},` + out.slice(afterOpen());
  }
  if (edits.Speed !== undefined) {
    const r = zombieLoreRange(out);
    if (r) {
      const body = out.slice(r.start, r.end);
      if (/^\s*Speed\s*=\s*\d+/m.test(body)) {
        out = out.slice(0, r.start) + body.replace(/^(\s*Speed\s*=\s*)\d+/m, (_m, p) => `${p}${edits.Speed}`) + out.slice(r.end);
      } else {
        out = out.slice(0, r.start) + `${eol}        Speed = ${edits.Speed},` + out.slice(r.start);
      }
    } else {
      out = out.slice(0, afterOpen()) + `${eol}    ZombieLore = {${eol}        Speed = ${edits.Speed},${eol}    },` + out.slice(afterOpen());
    }
  }
  return out;
}

/** Rejects a file that no longer looks like a SandboxVars table (unbalanced braces etc.). */
export function validateSandboxLua(lua: string): string | null {
  if (!OPEN.test(lua)) return "The result has no SandboxVars table.";
  let depth = 0;
  for (const ch of lua) {
    if (ch === "{") depth++;
    else if (ch === "}") depth--;
    if (depth < 0) return "The result has unbalanced braces.";
  }
  return depth === 0 ? null : "The result has unbalanced braces.";
}

/**
 * Bake the checkout/Settings values into the provisioning script so a fresh install or a
 * "Wipe & reinstall" starts configured: MEMORY_XMX_GB as an env var (the image reads it
 * at every start) and a seeded `servertest.ini` (PZ fills every other key with defaults;
 * the image's start.sh only edits the keys it owns). Zombies/Speed need the first-boot
 * SandboxVars file, so the auto-queued apply job sets them once it exists.
 * Returns the script unchanged when it is not the expected shape.
 */
export function applyZomboidSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !/docker run -d --name projectzomboid\b/.test(setupScript)) return setupScript;
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  let out = setupScript;
  const heap = Number(values.MEMORY_XMX_GB);
  if (Number.isFinite(heap) && heap > 0 && !/-e\s+MEMORY_XMX_GB=/.test(out)) {
    out = out.replace("docker run -d --name projectzomboid", () => `docker run -d --name projectzomboid -e MEMORY_XMX_GB=${Math.trunc(heap)}`);
  }
  const m = /-e\s+SERVER_NAME=(?:'([^']*)'|"([^"]*)"|(\S+))/.exec(out);
  const serverName = m ? (m[1] ?? m[2] ?? m[3] ?? "servertest") : "servertest";
  if (!/^[A-Za-z0-9_.-]{1,64}$/.test(serverName)) return out;
  const ini = pzIniEdits(values, PZ_INI_FIELDS).map((e) => `${e.key}=${e.value}`).join("\n") + "\n";
  const file = `${PZ_CONFIG_ROOT}/Server/${serverName}.ini`;
  const seed = `mkdir -p ${PZ_CONFIG_ROOT}/Server && { [ -f ${file} ] || printf '%s' ${q(ini)} > ${file}; } && `;
  return out.replace("docker run -d --name projectzomboid", () => `${seed}docker run -d --name projectzomboid`);
}
EOF

