import {
  PROJECTZOMBOID_SPEC, PZ_CONFIG_ROOT, PZ_CONTAINER, PZ_ENV_FILE, PZ_INI_FIELDS, PZ_SANDBOX_FIELDS, PZ_ENV_FIELDS,
  patchSandboxLua, pzEnvChanges, pzIniEdits, pzZombiesForFile, readSandboxSpeed, readSandboxVersion, readSandboxZombies, validateSandboxLua,
} from "../../lib/game-applier-specs/projectzomboid";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile, type FilePatchResult } from "./kit/config-file";
import { patchIni, readIni } from "./kit/ini-patch";
import { recreateWithEnv } from "./kit/env-recreate";
import { verifyReadback } from "./kit/readback";
import { withGameStopped } from "./kit/with-game-stopped";
import { applyZomboidAdmin } from "../zomboid-admin";

/**
 * Project Zomboid applier. Builds ON worker/zomboid-admin.ts (the admin password stays
 * exactly as it was; this file only calls it) and extends the family to the rest of its
 * schema. Mechanisms (and why) are documented in lib/game-applier-specs/projectzomboid.ts.
 *
 *  1. ini + SandboxVars.lua fields -> ONE stop-edit-start window (PZ rewrites these files itself)
 *  2. MaxPlayers / RCON_PASSWORD / MEMORY_XMX_GB -> env-recreate (the image re-applies them from env at every start)
 *  3. ADMIN_PASSWORD -> applyZomboidAdmin (db hash + env, own rollback)
 * Order = least to most invasive; a later failure leaves the earlier steps applied and says so.
 */

type AdminFn = typeof applyZomboidAdmin;

async function serverNameOf(ctx: ApplierContext): Promise<string | null> {
  const r = await ctx.guest.exec(`docker inspect ${shq(PZ_CONTAINER)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const env = (JSON.parse(r.stdout.trim()).Config?.Env ?? []) as string[];
    const hit = env.find((e) => e.startsWith("SERVER_NAME="));
    const name = hit ? hit.slice("SERVER_NAME=".length) : "servertest";
    return /^[A-Za-z0-9_.-]{1,64}$/.test(name) ? name : null;
  } catch {
    return null;
  }
}

export function makeZomboidApplier(adminFn: AdminFn = applyZomboidAdmin): GameConfigApplier {
  async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
    const { guest, values } = ctx;
    const iniFields = ctx.touched.filter((k) => (PZ_INI_FIELDS as readonly string[]).includes(k));
    const sbFields = ctx.touched.filter((k) => (PZ_SANDBOX_FIELDS as readonly string[]).includes(k));
    const envFields = ctx.touched.filter((k) => k in PZ_ENV_FIELDS);
    const wantAdmin = ctx.touched.includes("ADMIN_PASSWORD");
    const applied: string[] = [];
    const notes: string[] = [];
    let restarted = false;

    // ---- 1. files, with the game stopped ---------------------------------------------------
    if (iniFields.length || sbFields.length) {
      const name = await serverNameOf(ctx);
      if (!name) return { ok: false, applied: [], notes: ["Could not find the game container's settings, so nothing was changed."] };
      const iniPath = `${PZ_CONFIG_ROOT}/Server/${name}.ini`;
      const luaPath = `${PZ_CONFIG_ROOT}/Server/${name}_SandboxVars.lua`;
      const results: { label: string; res: FilePatchResult }[] = [];
      const missing: string[] = [];

      const edit = async (): Promise<{ ok: true; value: string[] } | { ok: false; note: string }> => {
        const done: string[] = [];
        if (iniFields.length) {
          const edits = pzIniEdits(values, iniFields);
          const res = await patchRemoteFile(guest, { path: iniPath, patch: (old) => patchIni(old, edits.map((e) => ({ key: e.key, value: e.value }))) });
          if (res.status === "invalid" || res.status === "failed") return { ok: false, note: res.reason };
          if (res.status === "missing") missing.push(...iniFields);
          else {
            results.push({ label: "ini", res });
            if (res.status === "changed") {
              const back = await guest.readFile(iniPath);
              const exp: Record<string, string> = Object.fromEntries(edits.map((e) => [e.key, e.value]));
              const act: Record<string, unknown> = {};
              for (const k of Object.keys(exp)) act[k] = back === null ? undefined : readIni(back, "", k);
              const rb = verifyReadback(exp, act);
              if (!rb.ok) return { ok: false, note: `Verification failed for ${rb.mismatched.join(", ")}; the previous settings were restored.` };
              done.push(`Updated the server settings file (${iniFields.join(", ")}).`);
            }
          }
        }
        if (sbFields.length) {
          const cur = await guest.readFile(luaPath);
          if (cur === null) missing.push(...sbFields);
          else {
            const ver = readSandboxVersion(cur);
            const e: { Zombies?: number; Speed?: number } = {};
            if (sbFields.includes("Speed")) e.Speed = Number(values.Speed);
            if (sbFields.includes("Zombies")) {
              if (ver === null) notes.push("Zombie Population was not applied: the sandbox file has no version marker, so we can't tell which population scale it uses.");
              else e.Zombies = pzZombiesForFile(Number(values.Zombies), ver);
            }
            if (e.Zombies !== undefined || e.Speed !== undefined) {
              const res = await patchRemoteFile(guest, { path: luaPath, patch: (old) => patchSandboxLua(old, e), validate: validateSandboxLua });
              if (res.status === "invalid" || res.status === "failed") return { ok: false, note: res.reason };
              if (res.status !== "missing") {
                results.push({ label: "sandbox", res });
                if (res.status === "changed") {
                  const back = (await guest.readFile(luaPath)) ?? "";
                  const bad: string[] = [];
                  if (e.Zombies !== undefined && readSandboxZombies(back) !== e.Zombies) bad.push("Zombies");
                  if (e.Speed !== undefined && readSandboxSpeed(back) !== e.Speed) bad.push("Speed");
                  if (bad.length) return { ok: false, note: `Verification failed for ${bad.join(", ")}; the previous settings were restored.` };
                  done.push(`Updated the sandbox settings (${[e.Zombies !== undefined ? "Zombies" : "", e.Speed !== undefined ? "Speed" : ""].filter(Boolean).join(", ")}).`);
                }
              }
            }
          }
        }
        return { ok: true, value: done };
      };
      const undo = async () => {
        for (const r of results) if (r.res.status === "changed") await r.res.restore();
      };

      // Nothing to change? Then do not stop the game at all: read first.
      const changedProbe = await (async () => {
        const iniNow = iniFields.length ? await guest.readFile(iniPath) : "";
        const luaNow = sbFields.length ? await guest.readFile(luaPath) : "";
        if (iniNow === null || luaNow === null) return true; // missing files are reported by the edit step
        let diff = false;
        if (iniFields.length) for (const e of pzIniEdits(values, iniFields)) if (readIni(iniNow, "", e.key) !== e.value) diff = true;
        if (sbFields.includes("Speed") && readSandboxSpeed(luaNow) !== Number(values.Speed)) diff = true;
        if (sbFields.includes("Zombies")) {
          const ver = readSandboxVersion(luaNow);
          if (ver === null || readSandboxZombies(luaNow) !== pzZombiesForFile(Number(values.Zombies), ver)) diff = true;
        }
        return diff;
      })();

      if (!changedProbe) {
        notes.push("The server's settings file already matched — nothing to change there.");
      } else {
        const stopped = await withGameStopped(guest, { unit: ctx.unit, container: PZ_CONTAINER, waitPort: ctx.waitPort, edit, undo });
        if (stopped.status === "failed") return { ok: false, applied: [], notes: [stopped.note] };
        if (stopped.status === "skipped") {
          // No service to stop: write anyway, but be honest that PZ may overwrite it and needs a restart.
          const r = await edit();
          if (!r.ok) { await undo(); return { ok: false, applied: [], notes: [r.note] }; }
          applied.push(...r.value);
          notes.push("We couldn't find the game's service to restart it. Restart the server for these settings to load.");
        } else {
          applied.push(...(stopped.value as string[]));
          notes.push(...stopped.notes);
          restarted = restarted || stopped.wasActive;
        }
      }
      if (missing.length) {
        notes.push(`The game hasn't created its settings files yet (it has never fully started), so these were saved but not applied: ${[...new Set(missing)].join(", ")}. Start the server once, then save again.`);
      }
      for (const r of results) if (r.res.status === "changed") await r.res.commit().catch(() => undefined);
    }

    // ---- 2. env fields: recreate the container --------------------------------------------
    const envChanges = pzEnvChanges(values, envFields);
    if (Object.keys(envChanges).length) {
      const r = await recreateWithEnv(guest, { container: PZ_CONTAINER, unit: ctx.unit, env: envChanges, envFile: PZ_ENV_FILE, waitPort: ctx.waitPort });
