import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Don't Starve Together (yeetzone/dontstarvetogether) — PURE half. Read off the image's own
 * boot scripts (build/scripts/boot/settings.sh, token.sh, mods.sh) and its image config
 * (STORAGE_PATH=/opt/storage, STEAM_PATH=/data, CLUSTER_NAME=cluster, SHARD_NAME=shard):
 *
 *  - The image turns env vars into `cluster.ini` / `server.ini` ONLY WHEN THOSE FILES DO NOT
 *    EXIST YET (`if [[ ! -f "$file_cluster" ]]`). After the first boot the env vars are inert,
 *    which is why changing a setting in Settings never reached the game. The truth is
 *    `$STORAGE_PATH/cluster/cluster.ini`, and the cluster token is `cluster_token.txt` beside it.
 *  - Our catalog script mounts `/opt/dst:/data` (the game binaries) but NOT /opt/storage, which
 *    the image declares as a VOLUME, so the cluster lives in an ANONYMOUS docker volume. The
 *    applier finds it through `docker inspect .Mounts` and edits it in place. It never
 *    recreates the container (a rebuilt container would get a fresh, empty volume = a lost world).
 *  - The DST binary re-serialises these ini files on start, so edits are made with the game
 *    stopped (stop-edit-start) and verified by reading each key back.
 *  - MODS is regenerated from the MODS env at every boot (mods.sh) and is owned by the Mods tab,
 *    so it is not handled here.
 */

const NOTE = "Applies on save: your server restarts briefly (players are disconnected).";

export const DST_SPEC: GameConfigApplierSpec = {
  family: "dst",
  fields: {
    NAME: { when: "recreate", note: NOTE },
    MAX_PLAYERS: { when: "recreate", note: NOTE },
    PASSWORD: { when: "recreate", secret: true, note: NOTE },
    TOKEN: { when: "recreate", secret: true, note: `${NOTE} Klei ties a token to one live server, so use a token that isn't running anywhere else.` },
    PVP_ENABLE: { when: "recreate", note: NOTE },
    INTENTION: { when: "recreate", note: NOTE },
    DESCRIPTION: { when: "recreate", note: NOTE },
    VOTE_KICK_ENABLE: { when: "recreate", note: NOTE },
  },
};

export const DST_CONTAINER = "dst";
export const DST_STORAGE_DEST = "/opt/storage";

type V = Record<string, string | number | boolean | undefined>;
export type DstEdit = { section: string; key: string; value: string; field: string };

const oneLine = (s: unknown) => String(s ?? "").replace(/[\r\n]+/g, " ").trim();

/** cluster.ini keys for the fields asked for (section + key names are the image's own, from settings.sh). */
export function dstClusterEdits(values: V, only: readonly string[]): DstEdit[] {
  const out: DstEdit[] = [];
  const b = (v: unknown) => (v === true ? "true" : "false");
  if (only.includes("NAME")) out.push({ field: "NAME", section: "NETWORK", key: "cluster_name", value: oneLine(values.NAME) });
  if (only.includes("DESCRIPTION")) out.push({ field: "DESCRIPTION", section: "NETWORK", key: "cluster_description", value: oneLine(values.DESCRIPTION) });
  if (only.includes("PASSWORD")) out.push({ field: "PASSWORD", section: "NETWORK", key: "cluster_password", value: oneLine(values.PASSWORD) });
  if (only.includes("INTENTION")) out.push({ field: "INTENTION", section: "NETWORK", key: "cluster_intention", value: oneLine(values.INTENTION) });
  if (only.includes("VOTE_KICK_ENABLE")) out.push({ field: "VOTE_KICK_ENABLE", section: "NETWORK", key: "enable_vote_kick", value: b(values.VOTE_KICK_ENABLE) });
  if (only.includes("MAX_PLAYERS")) out.push({ field: "MAX_PLAYERS", section: "GAMEPLAY", key: "max_players", value: String(Math.trunc(Number(values.MAX_PLAYERS ?? 10))) });
  if (only.includes("PVP_ENABLE")) out.push({ field: "PVP_ENABLE", section: "GAMEPLAY", key: "pvp", value: b(values.PVP_ENABLE) });
  return out;
}

/**
 * Bake the values into the provisioning script so a fresh install / reinstall creates its
 * cluster already configured. The image reads these env vars when it first generates
 * cluster.ini; applyGameConfigEnv only fills env vars the script already declares, and the
 * catalog script declares just NAME/MAX_PLAYERS/TOKEN, so the rest are added here.
 * Blank values are left out (the image treats unset and blank the same).
 */
export function applyDstSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !/docker run -d --name dst\b/.test(setupScript)) return setupScript;
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  const want: [string, string][] = [];
  const add = (env: string, v: string) => {
    if (v !== "" && !new RegExp(`-e\\s+${env}=`).test(setupScript)) want.push([env, v]);
  };
  add("PASSWORD", oneLine(values.PASSWORD));
  add("PVP_ENABLE", values.PVP_ENABLE === true ? "true" : "false");
  add("INTENTION", oneLine(values.INTENTION));
  add("DESCRIPTION", oneLine(values.DESCRIPTION));
  add("VOTE_KICK_ENABLE", values.VOTE_KICK_ENABLE === false ? "false" : "true");
  add("MODS", oneLine(values.MODS));
  if (!want.length) return setupScript;
  const flags = want.map(([k, v]) => `-e ${k}=${q(v)}`).join(" ");
  return setupScript.replace("docker run -d --name dst", () => `docker run -d --name dst ${flags}`);
}
