async function clusterDir(ctx: ApplierContext): Promise<string | null> {
  const r = await ctx.guest.exec(`docker inspect ${shq(DST_CONTAINER)} --format '{{json .Mounts}}'`);
  if (r.code !== 0) return null;
  try {
    const mounts = JSON.parse(r.stdout.trim()) as { Destination?: string; Source?: string }[];
    const m = mounts.find((x) => x.Destination === DST_STORAGE_DEST);
    return m?.Source && m.Source.startsWith("/") && !/[\r\n]/.test(m.Source) ? `${m.Source.replace(/\/$/, "")}/cluster` : null;
  } catch {
    return null;
  }
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const iniFields = ctx.touched.filter((k) => k !== "TOKEN");
  const wantToken = ctx.touched.includes("TOKEN") && String(values.TOKEN ?? "").trim() !== "";
  const dir = await clusterDir(ctx);
  if (!dir) return { ok: false, applied: [], notes: ["Could not find the game's data volume, so nothing was changed."] };
  const iniPath = `${dir}/cluster.ini`;
  const tokenPath = `${dir}/cluster_token.txt`;
  const edits = dstClusterEdits(values, iniFields);
  const token = String(values.TOKEN ?? "").trim();
  const results: FilePatchResult[] = [];
  const missing: string[] = [];

  const probe = async (): Promise<boolean> => {
    const ini = edits.length ? await guest.readFile(iniPath) : "";
    const tok = wantToken ? await guest.readFile(tokenPath) : "";
    if (ini === null || tok === null) return true; // missing -> reported by edit
    if (edits.some((e) => readIni(ini, e.section, e.key) !== e.value)) return true;
    return wantToken && tok.trim() !== token;
  };

  const edit = async (): Promise<{ ok: true; value: string[] } | { ok: false; note: string }> => {
    const done: string[] = [];
    if (edits.length) {
      const res = await patchRemoteFile(guest, {
        path: iniPath,
        patch: (old) => patchIni(old, edits.map((e) => ({ section: e.section, key: e.key, value: e.value })), { spaced: true }),
        validate: (c) => (/\[NETWORK\]/.test(c) ? null : "The result has no [NETWORK] section."),
      });
      if (res.status === "invalid" || res.status === "failed") return { ok: false, note: res.reason };
      if (res.status === "missing") missing.push(...iniFields);
      else {
        results.push(res);
        if (res.status === "changed") {
          const back = (await guest.readFile(iniPath)) ?? "";
          const rb = verifyReadback(
            Object.fromEntries(edits.map((e) => [e.field, e.value])),
            Object.fromEntries(edits.map((e) => [e.field, readIni(back, e.section, e.key)])),
          );
          if (!rb.ok) return { ok: false, note: `Verification failed for ${rb.mismatched.join(", ")}; the previous settings were restored.` };
          done.push(`Updated the cluster settings (${edits.map((e) => e.field).join(", ")}).`);
        }
      }
    }
    if (wantToken) {
      const res = await patchRemoteFile(guest, { path: tokenPath, patch: () => `${token}\n`, validate: (c) => (c.trim() ? null : "The token would be empty.") });
      if (res.status === "invalid" || res.status === "failed") return { ok: false, note: res.reason };
      if (res.status === "missing") {
        // The cluster has no token file at all (a server that never started online): create it.
        await guest.writeFile(tokenPath, `${token}\n`);
        done.push("Saved the Klei cluster token.");
        results.push({ status: "changed", restore: async () => void (await guest.exec(`rm -f ${shq(tokenPath)}`)), commit: async () => undefined });
      } else {
        results.push(res);
        if (res.status === "changed") done.push("Saved the new Klei cluster token.");
      }
    }
    return { ok: true, value: done };
  };
  const undo = async () => {
    for (const r of results) if (r.status === "changed") await r.restore();
  };

  if (!(await probe())) return { ok: true, applied: [], notes: ["The cluster settings already matched — nothing to change."] };

  const applied: string[] = [];
  const notes: string[] = [];
  const stopped = await withGameStopped(guest, { unit: ctx.unit, container: DST_CONTAINER, waitPort: ctx.waitPort, edit, undo });
  let restarted = false;
  if (stopped.status === "failed") return { ok: false, applied: [], notes: [stopped.note] };
  if (stopped.status === "skipped") {
    const r = await edit();
    if (!r.ok) { await undo(); return { ok: false, applied: [], notes: [r.note] }; }
    applied.push(...r.value);
    notes.push("We couldn't find the game's service to restart it. Restart the server for these settings to load.");
  } else {
    applied.push(...(stopped.value as string[]));
    notes.push(...stopped.notes);
    restarted = stopped.wasActive;
    if (!stopped.wasActive && applied.length) notes.push("Your server is stopped, so it was not started; the new settings are active the next time you press Start.");
  }
  if (missing.length) {
    notes.push(`The cluster hasn't been created yet (the game has never fully started), so these were saved but not applied: ${[...new Set(missing)].join(", ")}. Start the server once, then save again.`);
  }
  for (const r of results) if (r.status === "changed") await r.commit().catch(() => undefined);
  return { ok: true, applied, notes, restarted };
}

export const dstApplier: GameConfigApplier = { spec: DST_SPEC, apply };
