import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Unturned (imperialplugins/unturned) — PURE half. Facts: image config read from the registry
 * (User steam, entrypoint ./init.sh, env GAME_INSTALL_DIR/GAME_ID/SERVER_NAME/SERVER_TYPE only)
 * and the image's init.sh: the game is started as
 *   ./Unturned_Headless.x86_64 -logfile -batchmode -nographics +secureserver/"$SERVER_NAME"
 * so SERVER_NAME is the INSTANCE ID (the folder `Servers/<SERVER_NAME>`), not the name players
 * see, and the image exposes no gameplay env vars at all. Our catalog bind-mounts only
 * `/opt/unturned` -> `/home/steam/Unturned/Servers`.
 *
 * The game reads its settings from `Servers/<instance>/Server/Commands.dat` (Unturned's own
 * documented mechanism: one console command per line, run at startup): `Name`, `Password`,
 * `MaxPlayers`, `Mode` (Easy|Normal|Hard). The applier edits that file; the game reads it at
 * start, so these are "restart" fields. The instance id (SERVER_NAME) is NEVER changed: that
 * would silently start a brand-new world folder.
 *
 * serverType maps to the image's real SERVER_TYPE env var (vanilla | rm4 | rm5), consumed by
 * init.sh at start, so it is applied by recreating the container (brief restart).
 */

export const UNTURNED_SPEC: GameConfigApplierSpec = {
  family: "unturned",
  fields: {
    serverName: { when: "restart", note: "The name players see in the server list (Commands.dat `Name`). Takes effect after a restart." },
    password: { when: "restart", secret: true, note: "Commands.dat `Password`; blank removes it (public server). Takes effect after a restart." },
    maxPlayers: { when: "restart", note: "Commands.dat `MaxPlayers`. Takes effect after a restart." },
    difficulty: { when: "restart", note: "Commands.dat `Mode` (Easy, Normal, Hard). Takes effect after a restart." },
    serverType: { when: "recreate", note: "Applies on save: the container is rebuilt with SERVER_TYPE set (RocketMod 4/5 is installed at start; Vanilla starts without it). Your world is kept. Brief restart." },
  },
};

export const UNTURNED_CONTAINER = "unturned";
export const UNTURNED_SERVERS_DIR = "/opt/unturned";
export const UNTURNED_ENV_FILE = "/root/unturned.env";

type V = Record<string, string | number | boolean | undefined>;

/** schema field -> Commands.dat command (null value = remove the line). */
export function unturnedCommands(values: V, only: readonly string[]): Record<string, string | null> {
  const out: Record<string, string | null> = {};
  const one = (s: unknown) => String(s ?? "").replace(/[\r\n]+/g, " ").trim();
  if (only.includes("serverName")) out.Name = one(values.serverName) || null;
  if (only.includes("password")) out.Password = one(values.password) || null;
  if (only.includes("maxPlayers")) out.MaxPlayers = String(Math.trunc(Number(values.maxPlayers ?? 16)));
  if (only.includes("difficulty")) out.Mode = one(values.difficulty) || "Normal";
  return out;
}

/** Instance folder = the container's SERVER_NAME (path-safe check: it becomes part of a path). */
export function unturnedInstanceOk(name: string): boolean {
  return /^[A-Za-z0-9 _.-]{1,64}$/.test(name) && !name.startsWith(".");
}
export const unturnedCommandsPath = (instance: string) => `${UNTURNED_SERVERS_DIR}/${instance}/Server/Commands.dat`;

/** Set/replace/remove command lines (first word, case-insensitive). Everything else is preserved. */
export function patchCommandsDat(content: string, cmds: Record<string, string | null>): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  for (const [cmd, value] of Object.entries(cmds)) {
    const idx = lines.findIndex((l) => l.trim().split(/\s+/)[0]?.toLowerCase() === cmd.toLowerCase());
    if (value === null) {
      if (idx >= 0) lines.splice(idx, 1);
    } else if (idx >= 0) lines[idx] = `${cmd} ${value}`;
    else lines.push(`${cmd} ${value}`);
  }
  return lines.length ? lines.join(eol) + eol : "";
}

export function readCommandsDat(content: string, cmd: string): string | undefined {
  for (const l of content.split(/\r?\n/)) {
    const t = l.trim();
    const w = t.split(/\s+/)[0] ?? "";
    if (w.toLowerCase() === cmd.toLowerCase()) return t.slice(w.length).trim();
  }
  return undefined;
}

/**
 * Bake into the provisioning script: seed Commands.dat before first boot (the game keeps an
 * existing one) so a fresh install / reinstall starts with the customer's name, password,
 * player cap and difficulty. SERVER_TYPE is a plain `-e` the script already has and is
 * substituted by applyGameConfigEnv via the schema field's envKey.
 */
export function applyUnturnedSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !/docker run -d --name unturned\b/.test(setupScript)) return setupScript;
  const m = /-e\s+SERVER_NAME=(?:'([^']*)'|"([^"]*)"|(\S+))/.exec(setupScript);
  const instance = m ? (m[1] ?? m[2] ?? m[3] ?? "") : "";
  if (!unturnedInstanceOk(instance)) return setupScript;
  const cmds = unturnedCommands(values, ["serverName", "password", "maxPlayers", "difficulty"]);
  const body = patchCommandsDat("", cmds);
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  const file = unturnedCommandsPath(instance);
  const dir = file.slice(0, file.lastIndexOf("/"));
  const seed = `mkdir -p ${q(dir)} && { [ -f ${q(file)} ] || printf '%s' ${q(body)} > ${q(file)}; } && chown -R 1000:1000 ${UNTURNED_SERVERS_DIR} && `;
  return setupScript.replace("docker run -d --name unturned", () => `${seed}docker run -d --name unturned`);
}
EOF
