import {
  UNTURNED_CONTAINER, UNTURNED_ENV_FILE, UNTURNED_SPEC, patchCommandsDat, readCommandsDat, unturnedCommands, unturnedCommandsPath, unturnedInstanceOk,
} from "../../lib/game-applier-specs/unturned";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { shq } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { recreateWithEnv } from "./kit/env-recreate";
import { verifyReadback } from "./kit/readback";

/**
 * Unturned applier: Commands.dat (config-file strategy; the game reads it at start) for
 * name/password/max players/difficulty, env-recreate for SERVER_TYPE. The instance folder is
 * the container's SERVER_NAME and is never changed. See lib/game-applier-specs/unturned.ts.
 */

async function instanceOf(ctx: ApplierContext): Promise<string | null> {
  const r = await ctx.guest.exec(`docker inspect ${shq(UNTURNED_CONTAINER)} --format '{{json .}}'`);
  if (r.code !== 0) return null;
  try {
    const env = (JSON.parse(r.stdout.trim()).Config?.Env ?? []) as string[];
    const hit = env.find((e) => e.startsWith("SERVER_NAME="));
    const name = hit ? hit.slice("SERVER_NAME=".length) : "server";
    return unturnedInstanceOk(name) ? name : null;
  } catch {
    return null;
  }
}

async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const cmdFields = ctx.touched.filter((k) => k !== "serverType");
  const typeTouched = ctx.touched.includes("serverType");
  const applied: string[] = [];
  const notes: string[] = [];
  let restore: (() => Promise<void>) | null = null;
  let commit: (() => Promise<void>) | null = null;

  if (cmdFields.length) {
    const instance = await instanceOf(ctx);
    if (!instance) return { ok: false, applied: [], notes: ["Could not find the game container's instance name, so nothing was changed."] };
    const path = unturnedCommandsPath(instance);
    const want = unturnedCommands(values, cmdFields);
    const res = await patchRemoteFile(guest, { path, patch: (old) => patchCommandsDat(old, want) });
