import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * The Forest (jammsen/the-forest-dedicated-server) — PURE half. Read off the image's own scripts
 * (scripts/servermanager.sh, includes/config.sh, includes/security.sh, Dockerfile ENV):
 *
 *  - With SERVER_SETTINGS_MODE=auto (the image default) every start re-applies four env vars to
 *    `config.cfg` with sed: SERVER_NAME -> serverName, SERVER_PASSWORD -> serverPassword,
