export const THEFOREST_SED_ERROR = "Can't contain / \\ or & (the server's start-up script can't pass them through).";

type V = Record<string, string | number | boolean | undefined>;

export function theforestEnv(values: V, only: readonly string[]): Record<string, string> {
  const out: Record<string, string> = {};
  for (const [field, env] of Object.entries(THEFOREST_ENV_FIELDS)) {
    if (only.includes(field)) out[env] = String(values[field] ?? "").replace(/[\r\n]+/g, " ").trim();
  }
  return out;
}

export function theforestCfg(values: V, only: readonly string[]): Record<string, string> {
  const out: Record<string, string> = {};
  if (only.includes("maxPlayers")) out.serverPlayers = String(Math.min(8, Math.max(1, Math.trunc(Number(values.maxPlayers ?? 8)))));
  if (only.includes("difficulty")) out.difficulty = ["Peaceful", "Normal", "Hard"].includes(String(values.difficulty)) ? String(values.difficulty) : "Normal";
  return out;
}

/** `key value` config (config.cfg style): replace the line, or append it. `//` comment lines are kept. */
export function patchSpaceCfg(content: string, edits: Record<string, string>): string {
  const eol = content.includes("\r\n") ? "\r\n" : "\n";
  const lines = content.length ? content.split(/\r?\n/) : [];
  if (lines.length && lines[lines.length - 1] === "") lines.pop();
  for (const [key, value] of Object.entries(edits)) {
    const idx = lines.findIndex((l) => !l.trimStart().startsWith("//") && l.trim().split(/\s+/)[0] === key);
    if (idx >= 0) lines[idx] = `${key} ${value}`;
    else lines.push(`${key} ${value}`);
  }
  return lines.join(eol) + eol;
}

export function readSpaceCfg(content: string, key: string): string | undefined {
  for (const l of content.split(/\r?\n/)) {
    if (l.trimStart().startsWith("//")) continue;
    const t = l.trim();
    const w = t.split(/\s+/)[0] ?? "";
    if (w === key) return t.slice(w.length).trim();
  }
  return undefined;
}

/**
 * Bake into the provisioning script: the live catalog script sets none of SERVER_NAME /
 * SERVER_PASSWORD / ADMIN_PASSWORD (so applyGameConfigEnv had nothing to fill), which means
 * the image ran on its placeholder defaults. Add them from the customer's values. A blank
 * value is added as an explicit empty (admin password: blank = no admin password).
 * The Steam account token (SERVER_STEAM_ACCOUNT_TOKEN) is NOT handled here: it is not a
 * schema field and needs an owner decision.
 */
export function applyTheForestSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !/docker run -d --name theforest\b/.test(setupScript)) return setupScript;
  const q = (s: string) => `'${s.replace(/'/g, `'\\''`)}'`;
  const env = theforestEnv(values, Object.keys(THEFOREST_ENV_FIELDS));
  const flags = Object.entries(env)
    .filter(([k, v]) => !new RegExp(`-e\\s+${k}=`).test(setupScript) && (v !== "" || k === "ADMIN_PASSWORD"))
    .map(([k, v]) => `-e ${k}=${q(v)}`)
    .join(" ");
  if (!flags) return setupScript;
  return setupScript.replace("docker run -d --name theforest", () => `docker run -d --name theforest ${flags}`);
}
