import {
  THEFOREST_CFG_FIELDS, THEFOREST_CONFIG, THEFOREST_CONTAINER, THEFOREST_ENV_FIELDS, THEFOREST_ENV_FILE, THEFOREST_SPEC,
  patchSpaceCfg, readSpaceCfg, theforestCfg, theforestEnv,
} from "../../lib/game-applier-specs/theforest";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { recreateWithEnv } from "./kit/env-recreate";
import { verifyReadback } from "./kit/readback";

/**
 * The Forest applier: config.cfg (serverPlayers, difficulty; read at start) + env-recreate
 * (SERVER_NAME / SERVER_PASSWORD / ADMIN_PASSWORD, which the image re-applies to config.cfg at
 * every start). Mechanisms and sources: lib/game-applier-specs/theforest.ts.
 * If the recreate fails the config.cfg edit is rolled back, so failure means "nothing changed".
 */
async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const cfgFields = ctx.touched.filter((k) => (THEFOREST_CFG_FIELDS as readonly string[]).includes(k));
  const envFields = ctx.touched.filter((k) => k in THEFOREST_ENV_FIELDS);
  const applied: string[] = [];
  const notes: string[] = [];
  let restore: (() => Promise<void>) | null = null;
  let commit: (() => Promise<void>) | null = null;

  if (cfgFields.length) {
    const want = theforestCfg(values, cfgFields);
    const res = await patchRemoteFile(guest, { path: THEFOREST_CONFIG, patch: (old) => patchSpaceCfg(old, want) });
    if (res.status === "invalid" || res.status === "failed") return { ok: false, applied: [], notes: [res.reason, "Nothing was changed on your server."] };
    if (res.status === "missing") {
      notes.push(`The Forest hasn't created its config file yet (the server has never fully started), so these were saved but not applied: ${cfgFields.join(", ")}. Start the server once, then save again.`);
    } else if (res.status === "unchanged") {
      notes.push("config.cfg already matched — nothing to change there.");
    } else {
      restore = res.restore;
      commit = res.commit;
      const back = (await guest.readFile(THEFOREST_CONFIG)) ?? "";
      const rb = verifyReadback(want, Object.fromEntries(Object.keys(want).map((k) => [k, readSpaceCfg(back, k)])));
      if (!rb.ok) {
        await res.restore();
        return { ok: false, applied: [], notes: [`Verification failed for ${rb.mismatched.join(", ")}; the previous config was restored. Nothing was changed on your server.`] };
      }
      applied.push(`Updated config.cfg (${cfgFields.join(", ")}); it is read when the server starts.`);
    }
  }

  let restarted = false;
  const env = theforestEnv(values, envFields);
  if (Object.keys(env).length) {
    const r = await recreateWithEnv(guest, { container: THEFOREST_CONTAINER, unit: ctx.unit, env, envFile: THEFOREST_ENV_FILE, waitPort: ctx.waitPort });
    if (r.status === "failed") {
      if (restore) await restore().catch(() => undefined);
      return { ok: false, applied: [], notes: [r.note, ...(restore ? ["Your config.cfg edit was put back as well, so nothing was changed."] : [])] };
    }
    if (r.status === "recreated") {
      restarted = r.wasActive;
      applied.push(`Rebuilt the game container with the new ${envFields.join(", ")}.`);
      notes.push(...r.notes);
      if (!r.wasActive) notes.push("Your server is stopped, so it was not started; the new settings are active the next time you press Start.");
    } else notes.push("The game container already had those values — nothing to change there.");
  }
  if (commit) await commit().catch(() => undefined);
  return { ok: true, applied, notes, restarted };
}

export const theforestApplier: GameConfigApplier = { spec: THEFOREST_SPEC, apply };
