export const SONSOFTHEFOREST_SPEC: GameConfigApplierSpec = {
  family: "sonsoftheforest",
  fields: {
    serverName: { when: "recreate", note: NOTE },
    password: { when: "recreate", secret: true, note: `${NOTE} Blank = public.` },
    maxPlayers: { when: "recreate", note: NOTE },
    gameMode: { when: "recreate", note: `${NOTE} Only affects a world that has not been started yet; an existing save keeps the mode it was created with.` },
  },
};

export const SOTF_CONTAINER = "sonsoftheforest";
export const SOTF_CONFIG = "/opt/sonsoftheforest/userdata/dedicatedserver.cfg";

type V = Record<string, string | number | boolean | undefined>;

export function sotfSettings(values: V, only: readonly string[]): Record<string, string | number> {
  const out: Record<string, string | number> = {};
  const one = (s: unknown) => String(s ?? "").replace(/[\r\n]+/g, " ").trim();
  if (only.includes("serverName")) out.ServerName = one(values.serverName);
  if (only.includes("password")) out.Password = String(values.password ?? "").replace(/[\r\n]+/g, " ");
  if (only.includes("maxPlayers")) out.MaxPlayers = Math.min(8, Math.max(1, Math.trunc(Number(values.maxPlayers ?? 8))));
  if (only.includes("gameMode")) out.GameMode = ["Normal", "Hard", "Peaceful", "Creative"].includes(String(values.gameMode)) ? String(values.gameMode) : "Normal";
  return out;
}

/** The image's shipped example config (configs/dedicatedserver.cfg.example), used to seed a fresh install. */
const EXAMPLE = {
  IpAddress: "0.0.0.0", GamePort: 8766, QueryPort: 27016, BlobSyncPort: 9700,
  ServerName: "Nxeon Sons of the Forest", MaxPlayers: 8, Password: "", LanOnly: false, SaveSlot: 1, SaveMode: "Continue",
  GameMode: "Normal", SaveInterval: 600, IdleDayCycleSpeed: 0.0, IdleTargetFramerate: 5, ActiveTargetFramerate: 60,
  LogFilesEnabled: false, TimestampLogFilenames: true, TimestampLogEntries: true, SkipNetworkAccessibilityTest: true,
  GameSettings: {}, CustomGameModeSettings: {},
};

/**
 * Bake into the provisioning script: pre-create dedicatedserver.cfg (the image only copies its
 * example when the file is missing), so a fresh install / reinstall starts with the customer's
 * name, password, player cap and game mode and needs no restart afterwards. SaveMode is always
 * seeded as Continue (a fresh install has no save, so the game starts a new world anyway).
 */
export function applySonsOfTheForestSetup(setupScript: string, values: V | null | undefined): string {
  if (!values || !/docker run -d --name sonsoftheforest\b/.test(setupScript)) return setupScript;
  const cfg = { ...EXAMPLE, ...sotfSettings(values, ["serverName", "password", "maxPlayers", "gameMode"]) };
  const json = JSON.stringify(cfg, null, 2) + "\n";
