import { SONSOFTHEFOREST_SPEC, SOTF_CONFIG, SOTF_CONTAINER, sotfSettings } from "../../lib/game-applier-specs/sonsoftheforest";
import type { ApplierContext, ApplyOutcome, GameConfigApplier } from "./types";
import { patchRemoteFile } from "./kit/config-file";
import { patchJson, readJson } from "./kit/json-patch";
import { verifyReadback } from "./kit/readback";
import { withGameStopped } from "./kit/with-game-stopped";

/**
 * Sons of the Forest applier: JSON keys in userdata/dedicatedserver.cfg, edited with the game
 * stopped (the game rewrites that file). SaveMode is intentionally not handled (see the spec).
 */
async function apply(ctx: ApplierContext): Promise<ApplyOutcome> {
  const { guest, values } = ctx;
  const want = sotfSettings(values, ctx.touched);
  const current = await guest.readFile(SOTF_CONFIG);
  if (current === null) {
    return { ok: true, applied: [], notes: [`Sons of the Forest hasn't created its config file yet (the server has never fully started), so these were saved but not applied: ${ctx.touched.join(", ")}. Start the server once, then save again.`] };
  }
  let would: string;
  try {
    would = patchJson(current, Object.entries(want).map(([k, v]) => ({ path: [k], value: v })));
  } catch {
    return { ok: false, applied: [], notes: ["The server's config file could not be read as JSON, so it was left untouched."] };
  }
  if (would === current) return { ok: true, applied: [], notes: ["dedicatedserver.cfg already matched — nothing to change."] };

  let restore: (() => Promise<void>) | null = null;
  let commit: (() => Promise<void>) | null = null;
  const stopped = await withGameStopped(guest, {
    unit: ctx.unit,
    container: SOTF_CONTAINER,
    waitPort: ctx.waitPort,
    undo: async () => void (await restore?.()),
    edit: async () => {
      const res = await patchRemoteFile(guest, {
        path: SOTF_CONFIG,
        patch: (old) => patchJson(old, Object.entries(want).map(([k, v]) => ({ path: [k], value: v }))),
        validate: (c) => { try { JSON.parse(c); return null; } catch { return "The result is not valid JSON."; } },
      });
      if (res.status === "invalid" || res.status === "failed") return { ok: false, note: res.reason };
      if (res.status !== "changed") return { ok: true, value: false };
      restore = res.restore;
      commit = res.commit;
      const back = (await guest.readFile(SOTF_CONFIG)) ?? "{}";
      const rb = verifyReadback(want, Object.fromEntries(Object.keys(want).map((k) => [k, readJson(back, [k])])));
      if (!rb.ok) return { ok: false, note: `Verification failed for ${rb.mismatched.join(", ")}; the previous config was restored.` };
      return { ok: true, value: true };
    },
  });
  if (stopped.status === "failed") return { ok: false, applied: [], notes: [stopped.note] };
  let notes: string[] = [];
  let restarted = false;
  if (stopped.status === "skipped") {
    // No service to stop: write it anyway, but say the game may need a restart to read it.
    const res = await patchRemoteFile(guest, { path: SOTF_CONFIG, patch: (old) => patchJson(old, Object.entries(want).map(([k, v]) => ({ path: [k], value: v }))) });
    if (res.status === "invalid" || res.status === "failed") return { ok: false, applied: [], notes: [res.reason] };
    if (res.status === "changed") commit = res.commit;
    notes = ["We couldn't find the game's service to restart it. Restart the server for these settings to load."];
  } else {
    notes = [...stopped.notes];
    restarted = stopped.wasActive;
    if (!stopped.wasActive) notes.push("Your server is stopped, so it was not started; the new settings are active the next time you press Start.");
  }
  if (commit) await (commit as () => Promise<void>)().catch(() => undefined);
  return { ok: true, applied: [`Updated dedicatedserver.cfg (${ctx.touched.join(", ")}) and verified it.`], notes, restarted };
}

export const sonsoftheforestApplier: GameConfigApplier = { spec: SONSOFTHEFOREST_SPEC, apply };
EOF

