import type { GameConfigApplierSpec } from "../game-config-appliers";

/**
 * Stationeers (didstopia/stationeers-server) — PURE half. Read off the image config (registry)
 * and its start script (start_stationeers.sh): the four STATIONEERS_* env vars below are turned
 * into launch args at EVERY start (`-servername=`, `-worldname= -loadworld=`, `-autosaveinterval=`,
 * `-password=`), the image's own docs call env vars the one supported path, and the saves live in
 * the bind mount `/opt/stationeers` -> `/steamcmd/stationeers`. So all four are applied by
 * recreating the container with new env (volumes untouched, old saves kept).
 *
 * Launch-script limit (read in the script): the arguments are built as one string and expanded
 * unquoted, so a SPACE in the server name, world name or password splits it into separate
 * arguments (and the literal quote around the name is kept). The schema therefore rejects
 * spaces and quote characters in those three fields.
 */

