import { validateConfig } from "../game-config";
import { applyZomboidSetup } from "./projectzomboid";
import { applyDstSetup } from "./dst";
import { applyUnturnedSetup } from "./unturned";
import { applyTheForestSetup } from "./theforest";
import { applySonsOfTheForestSetup } from "./sonsoftheforest";

/**
 * One entry point for the "bake the customer's settings into the provisioning script" step of the
 * mixed-mechanism families (so worker/game-variant.ts needs a single call). Each per-family function
 * is a pure string rewrite that leaves the script unchanged when it is not the expected shape.
 * Stationeers needs none: all its fields are plain `-e STATIONEERS_*` env that applyGameConfigEnv fills.
 */
export function applyMixedFamilySetup(script: string, family: string | null, gameConfig: unknown): string {
  if (!family || !gameConfig) return script;
  const bake: Record<string, (s: string, v: Record<string, string | number | boolean>) => string> = {
    projectzomboid: applyZomboidSetup,
    dst: applyDstSetup,
    unturned: applyUnturnedSetup,
    theforest: applyTheForestSetup,
    sonsoftheforest: applySonsOfTheForestSetup,
  };
  const fn = bake[family];
  if (!fn) return script;
  const v = validateConfig(family, gameConfig as Record<string, unknown>);
  return v.ok ? fn(script, v.values) : script;
}
