import { fakeGuest, IMAGE_ENV, type FakeOpts } from "./_fake-docker-guest";
import { runApplier } from "../worker/game-config-appliers/run";
import type { GameConfigApplier, Guest } from "../worker/game-config-appliers/types";
import { validateConfig } from "../lib/game-config";

/** A fake guest for one container (any family): files + container fields + the `.Mounts` query the DST applier makes. */
export type MixedOpts = FakeOpts & {
  family: string;
  image: string;
  env?: string[];
  cmd?: string[];
  binds?: string[];
  ports?: Record<string, { HostIp: string; HostPort: string }[]>;
  mounts?: { Destination: string; Source: string }[];
  /** the first `systemctl start` fails (simulates a game that won't come back after a file edit) */
  failStartOnce?: boolean;
};

export function mixedGuest(o: MixedOpts) {
  const g = fakeGuest({ ...o, container: o.container ?? o.family, unit: o.unit ?? `${o.family}.service` });
  const c = g.containers.get(g.name)!;
  c.image = o.image;
  c.env = [...IMAGE_ENV, ...(o.env ?? [])];
  c.cmd = o.cmd ?? [];
  c.binds = (o.binds ?? []).slice().sort();
  c.ports = o.ports ?? { "27015/udp": [{ HostIp: "", HostPort: "27015" }] };
  let failed = false;
  const inner = g.guest;
  const guest: Guest = {
    ...inner,
    async exec(cmd, t) {
      g.log.push(cmd);
      if (cmd.includes("{{json .Mounts}}")) return { code: 0, stdout: JSON.stringify(o.mounts ?? []), stderr: "" };
      if (o.failStartOnce && !failed && /^systemctl start /.test(cmd.trim()) && g.st.active === false) {
        failed = true;
        return { code: 1, stdout: "", stderr: "boom" };
      }
      return inner.exec(cmd, t);
    },
  };
  return { ...g, guest };
}
export type MixedGuest = ReturnType<typeof mixedGuest>;

export function defaults(family: string, over: Record<string, string | number | boolean> = {}) {
  const v = validateConfig(family, {});
  if (!v.ok) throw new Error(`defaults for ${family} do not validate: ${JSON.stringify(v)}`);
  return { ...v.values, ...over };
}

export function runFamily(applier: GameConfigApplier, g: MixedGuest, values: Record<string, string | number | boolean>, changed: string[] | undefined, restartRequested = false) {
  return runApplier(applier, { server: { id: "s1" }, values, changed, restartRequested, guest: g.guest, unit: g.unit, waitPort: async () => ({ ok: true }) });
}

export const noSecretIn = (g: MixedGuest, out: unknown, secret: string) => {
  const blob = JSON.stringify(out);
  return !blob.includes(secret) && !g.log.some((l) => l.includes(secret) && !l.startsWith("write "));
};
