import { fakeGuest, IMAGE_ENV, type FakeOpts } from "./_fake-docker-guest";
import { runApplier } from "../worker/game-config-appliers/run";
import type { GameConfigApplier, Guest } from "../worker/game-config-appliers/types";
import { validateConfig } from "../lib/game-config";

/** A fake guest for one container (any family): files + container fields + the `.Mounts` query the DST applier makes. */
