import { test } from "node:test";
import assert from "node:assert/strict";
import { makeZomboidApplier } from "../worker/game-config-appliers/projectzomboid";
import {
  PROJECTZOMBOID_SPEC, applyZomboidSetup, patchSandboxLua, pzZombiesForFile, readSandboxSpeed, readSandboxVersion, readSandboxZombies, validateSandboxLua,
} from "../lib/game-applier-specs/projectzomboid";
import { GAME_CONFIG_SCHEMAS } from "../lib/game-config";
import { applyGameConfigEnv } from "../worker/game-variant";
import { defaults, mixedGuest, noSecretIn, runFamily } from "./_cfg-mixed-helpers";

const INI_PATH = "/opt/projectzomboid/config/Server/servertest.ini";
const LUA_PATH = "/opt/projectzomboid/config/Server/servertest_SandboxVars.lua";
// Shapes taken from the image's start.sh (it only ever sets these keys) and PZ's own file layout.
const INI = "DefaultPort=16261\nUDPPort=16262\nRCONPort=27015\nRCONPassword=rc0nsecret\nMaxPlayers=16\nPublicName=My Server\nPVP=true\nPauseEmpty=true\nMods=\n";
const lua = (version: number, zombies: number, speed: number) =>
  `SandboxVars = {\n    VERSION = ${version},\n    Zombies = ${zombies},\n    Distribution = 1,\n    ZombieLore = {\n        Speed = ${speed},\n        Strength = 2,\n    },\n    ZombieConfig = {\n        PopulationMultiplier = 1.0,\n    },\n}\n`;

const PZ_ENV = ["SERVER_NAME=servertest", "ADMIN_USERNAME=admin", "ADMIN_PASSWORD=adm1npw", "RCON_PASSWORD=rc0nsecret", "MAX_PLAYERS=16", "MEMORY_XMX_GB=4"];
const mk = (files: Record<string, string> = { [INI_PATH]: INI, [LUA_PATH]: lua(6, 4, 2) }, extra: { active?: boolean; failStartOnce?: boolean } = {}) =>
  mixedGuest({ family: "projectzomboid", image: "indifferentbroccoli/projectzomboid-server-docker", env: PZ_ENV, binds: ["/opt/projectzomboid/config:/project-zomboid-config", "/opt/projectzomboid/server:/project-zomboid"], files, ...extra });
const adminCalls: unknown[] = [];
const applier = makeZomboidApplier(async (_g, _v, _d, opts) => {
  adminCalls.push(opts);
  return { ok: true, applied: ["Admin password applied and verified."], notes: [], restarted: true };
});
const V = (over = {}) => defaults("projectzomboid", over);

test("spec keys all exist in the schema; only ADMIN_USERNAME is honestly left saved-only", () => {
  const keys = GAME_CONFIG_SCHEMAS.projectzomboid.fields.map((f) => f.key);
  for (const k of Object.keys(PROJECTZOMBOID_SPEC.fields)) assert.ok(keys.includes(k), k);
  assert.deepEqual(keys.filter((k) => !(k in PROJECTZOMBOID_SPEC.fields)), ["ADMIN_USERNAME"]);
});

test("PublicName / PVP / PauseEmpty land in servertest.ini with the game stopped, other keys kept, game restarted", async () => {
  for (const [field, value, expect] of [["PublicName", "Nxeon Survivors", "PublicName=Nxeon Survivors"], ["PVP", false, "PVP=false"], ["PauseEmpty", false, "PauseEmpty=false"]] as const) {
    const g = mk();
    const out = await runFamily(applier, g, V({ [field]: value }), [field]);
    assert.equal(out.ok, true, field);
    const ini = g.files.get(INI_PATH)!;
    assert.ok(ini.includes(expect), field);
    assert.ok(ini.includes("RCONPassword=rc0nsecret") && ini.includes("Mods="), "other keys preserved");
    assert.equal(out.restarted, true);
    assert.equal(g.st.active, true, "game running again");
    const stopAt = g.log.findIndex((l) => l.startsWith("systemctl stop"));
    const writeAt = g.log.findIndex((l) => l === `write ${INI_PATH}`);
    const startAt = g.log.findIndex((l) => l.startsWith("systemctl start"));
    assert.ok(stopAt >= 0 && stopAt < writeAt && writeAt < startAt, "stop -> write -> start");
    assert.equal(g.st.created, 0, "no container recreate for file fields");
  }
});

test("Zombies / Speed are written into SandboxVars.lua (Build 42 scale as-is, Build 41 file mapped)", async () => {
  const g = mk();
  const out = await runFamily(applier, g, V({ Zombies: "5", Speed: "1" }), ["Zombies", "Speed"]);
  assert.equal(out.ok, true);
  const f = g.files.get(LUA_PATH)!;
  assert.equal(readSandboxZombies(f), 5);
  assert.equal(readSandboxSpeed(f), 1);
  assert.ok(f.includes("Strength = 2") && f.includes("PopulationMultiplier = 1.0"), "unrelated keys preserved");
  // B41 (VERSION 5) five-step scale: schema "High"(3) -> file 2, "Normal"(4) -> 3, "None"(6) -> 5
  assert.deepEqual([1, 2, 3, 4, 5, 6].map((n) => pzZombiesForFile(n, 5)), [1, 2, 2, 3, 4, 5]);
  const g41 = mk({ [INI_PATH]: INI, [LUA_PATH]: lua(5, 3, 2) });
  await runFamily(applier, g41, V({ Zombies: "6" }), ["Zombies"]);
  assert.equal(readSandboxZombies(g41.files.get(LUA_PATH)!), 5);
});

test("a sandbox file with no VERSION marker is not guessed at for Zombies", async () => {
  const g = mk({ [INI_PATH]: INI, [LUA_PATH]: "SandboxVars = {\n    Zombies = 4,\n}\n" });
  const out = await runFamily(applier, g, V({ Zombies: "2" }), ["Zombies"]);
  assert.equal(readSandboxZombies(g.files.get(LUA_PATH)!), 4);
  assert.match(out.notes.join(" "), /version marker/);
});

test("lua patcher: inserts missing Speed/ZombieLore, rejects a broken result", () => {
  assert.equal(readSandboxSpeed(patchSandboxLua("SandboxVars = {\n    VERSION = 6,\n}\n", { Speed: 3 })), 3);
  assert.equal(readSandboxSpeed(patchSandboxLua("SandboxVars = {\n    ZombieLore = {\n        Strength = 1,\n    },\n}\n", { Speed: 3 })), 3);
  assert.equal(readSandboxVersion(lua(6, 4, 2)), 6);
  assert.equal(validateSandboxLua("SandboxVars = {\n  A = {\n}\n") !== null, true);
  assert.throws(() => patchSandboxLua("not lua", { Speed: 1 }));
});

test("MaxPlayers / RCON_PASSWORD / MEMORY_XMX_GB rebuild the container with new env (volumes kept); password never leaks", async () => {
  const g = mk();
  const out = await runFamily(applier, g, V({ MaxPlayers: 24, RCON_PASSWORD: "N3w-rcon-pw", MEMORY_XMX_GB: 6 }), ["MaxPlayers", "RCON_PASSWORD", "MEMORY_XMX_GB"]);
  assert.equal(out.ok, true);
  const c = g.containers.get("projectzomboid")!;
  assert.ok(c.env.includes("MAX_PLAYERS=24") && c.env.includes("RCON_PASSWORD=N3w-rcon-pw") && c.env.includes("MEMORY_XMX_GB=6"));
  assert.ok(c.env.includes("ADMIN_PASSWORD=adm1npw"), "other env carried");
  assert.deepEqual(c.binds, ["/opt/projectzomboid/config:/project-zomboid-config", "/opt/projectzomboid/server:/project-zomboid"]);
  assert.equal(out.restarted, true);
  assert.ok(noSecretIn(g, out, "N3w-rcon-pw"));
  assert.equal(g.files.has("/root/projectzomboid.env"), false, "env file removed");
});

test("a blank RCON password means 'keep the current one' (never blanks it)", async () => {
  const g = mk();
  const out = await runFamily(applier, g, V({ RCON_PASSWORD: "" }), ["RCON_PASSWORD"]);
  assert.equal(out.ok, true);
  assert.ok(g.containers.get("projectzomboid")!.env.includes("RCON_PASSWORD=rc0nsecret"));
  assert.equal(g.st.created, 0);
});

test("idempotent: same values again change nothing and do not restart", async () => {
  const g = mk();
  const out = await runFamily(applier, g, V({ PublicName: "My Server", PVP: true, PauseEmpty: true, Zombies: "4", Speed: "2", MaxPlayers: 16, MEMORY_XMX_GB: 4 }), ["PublicName", "PVP", "PauseEmpty", "Zombies", "Speed", "MaxPlayers", "MEMORY_XMX_GB"]);
  assert.equal(out.ok, true);
  assert.ok(!out.restarted);
  assert.equal(g.log.some((l) => l.startsWith("systemctl stop")), false);
  assert.equal(g.st.created, 0);
});

test("a server the customer stopped is edited but not started", async () => {
  const g = mk(undefined, { active: false });
  const out = await runFamily(applier, g, V({ PVP: false }), ["PVP"]);
  assert.equal(out.ok, true);
  assert.ok(g.files.get(INI_PATH)!.includes("PVP=false"));
  assert.equal(g.st.active, false);
  assert.match(out.notes.join(" "), /stopped/);
});

test("rollback: a file that would be invalid is refused, nothing written, the game is running again", async () => {
  const g = mk({ [INI_PATH]: INI, [LUA_PATH]: "garbage with no sandbox table" });
  const out = await runFamily(applier, g, V({ Speed: "3" }), ["Speed"]);
  assert.equal(out.ok, false);
  assert.equal(g.files.get(LUA_PATH), "garbage with no sandbox table");
  assert.equal(g.st.active, true);
});

test("rollback: the game not starting after the edit puts the previous ini back and starts it", async () => {
  const g = mk(undefined, { failStartOnce: true });
  const out = await runFamily(applier, g, V({ PublicName: "Broken Name" }), ["PublicName"]);
  assert.equal(out.ok, false);
  assert.equal(g.files.get(INI_PATH), INI);
  assert.equal(g.st.active, true);
});

test("files not created yet (game never started): saved-but-not-applied, honest, no stop", async () => {
  const g = mk({});
  const out = await runFamily(applier, g, V({ PVP: false }), ["PVP"]);
  assert.equal(out.ok, true);
  assert.match(out.notes.join(" "), /never fully started/);
  assert.equal(g.log.some((l) => l.startsWith("systemctl stop")), false);
});

test("ADMIN_PASSWORD is delegated to the existing zomboid-admin module; ADMIN_USERNAME is reported as saved-only", async () => {
  adminCalls.length = 0;
  const g = mk();
  const out = await runFamily(applier, g, V({ ADMIN_PASSWORD: "Br4nd-new-pw", ADMIN_USERNAME: "boss" }), ["ADMIN_PASSWORD", "ADMIN_USERNAME"]);
  assert.equal(out.ok, true);
  assert.deepEqual(adminCalls, [{ changed: ["ADMIN_PASSWORD"] }]);
  assert.match(out.notes.join(" "), /ADMIN_USERNAME/);
  assert.match(out.applied.join(" "), /Admin password applied/);
});

test("a failing admin step fails the whole apply but keeps the earlier steps' honest report", async () => {
  const failing = makeZomboidApplier(async () => ({ ok: false, applied: [], notes: ["Could not stop the game cleanly."] }));
  const g = mk();
  const out = await runFamily(failing, g, V({ PVP: false, ADMIN_PASSWORD: "whatever-pw1" }), ["PVP", "ADMIN_PASSWORD"]);
  assert.equal(out.ok, false);
  assert.ok(g.files.get(INI_PATH)!.includes("PVP=false"));
  assert.match(out.notes.join(" "), /Could not stop/);
});

test("invalid saved settings ({}): the runner refuses instead of writing blanks", async () => {
  const g = mk();
  const out = await runFamily(applier, g, {}, ["PublicName"]);
  assert.equal(out.ok, false);
  assert.equal(g.files.get(INI_PATH), INI);
});

test("fresh install bake: heap env + seeded servertest.ini; checkout env placeholders still filled", () => {
  const script = "curl -fsSL https://get.docker.com | sh && docker run -d --name projectzomboid -e PUID=1000 -e SERVER_NAME=servertest -e ADMIN_USERNAME=admin -e ADMIN_PASSWORD=changeme12 -e RCON_PASSWORD=changeme12 -e MAX_PLAYERS=16 -v /opt/projectzomboid/config:/project-zomboid-config indifferentbroccoli/projectzomboid-server-docker";
  const cfg = V({ PublicName: "It's Mine", PVP: false, MaxPlayers: 12, MEMORY_XMX_GB: 6 });
  const baked = applyZomboidSetup(applyGameConfigEnv(script, "projectzomboid", cfg), cfg);
  assert.match(baked, /-e MEMORY_XMX_GB=6/);
  assert.match(baked, /-e MAX_PLAYERS='12'/);
  assert.match(baked, /servertest\.ini/);
  assert.match(baked, /PublicName=It'\\''s Mine/);
  assert.match(baked, /PVP=false/);
  assert.equal(applyZomboidSetup("something else entirely", cfg), "something else entirely");
});

