  const out = await runFamily(sonsoftheforestApplier, g, V({ serverName: "jammsen-docker-generated-123", maxPlayers: 8, gameMode: "Normal", password: "" }), ["serverName", "maxPlayers", "gameMode", "password"]);
  assert.equal(out.ok, true);
  assert.equal(g.log.some((l) => l.startsWith("systemctl stop")), false);
  assert.equal(g.files.get(CFG), EXAMPLE);
