test("rollback: a config that is not JSON is left untouched; a game that won't start restores the file", async () => {
  const bad = mk({ [CFG]: "{ nope" });
  const out = await runFamily(sonsoftheforestApplier, bad, V({ maxPlayers: 3 }), ["maxPlayers"]);
  assert.equal(out.ok, false);
  assert.equal(bad.files.get(CFG), "{ nope");
  const g = mk(undefined, { failStartOnce: true });
  const out2 = await runFamily(sonsoftheforestApplier, g, V({ gameMode: "Peaceful" }), ["gameMode"]);
  assert.equal(out2.ok, false);
  assert.equal(g.files.get(CFG), EXAMPLE);
  assert.equal(g.st.active, true);
});

test("stopped server is edited but left stopped; missing config is saved-but-not-applied", async () => {
  const g = mk(undefined, { active: false });
  const out = await runFamily(sonsoftheforestApplier, g, V({ maxPlayers: 2 }), ["maxPlayers"]);
  assert.equal(cfg(g).MaxPlayers, 2);
  assert.equal(g.st.active, false);
  assert.match(out.notes.join(" "), /stopped/);
  const none = mk({});
  const out2 = await runFamily(sonsoftheforestApplier, none, V({ maxPlayers: 2 }), ["maxPlayers"]);
  assert.equal(out2.ok, true);
  assert.match(out2.notes.join(" "), /never fully started/);
});

