import { test } from "node:test";
import assert from "node:assert/strict";
import { stationeersApplier } from "../worker/game-config-appliers/stationeers";
import { STATIONEERS_SPEC } from "../lib/game-applier-specs/stationeers";
import { GAME_CONFIG_SCHEMAS, validateConfig } from "../lib/game-config";
import { applyGameConfigEnv } from "../worker/game-variant";
import { defaults, mixedGuest, noSecretIn, runFamily } from "./_cfg-mixed-helpers";

const mk = (extra: { active?: boolean; createFails?: boolean } = {}) =>
  mixedGuest({
    family: "stationeers", image: "didstopia/stationeers-server:latest",
    env: ["STATIONEERS_SERVER_NAME=Nxeon", "STATIONEERS_WORLD_NAME=Nxeon World", "STATIONEERS_SERVER_PASSWORD=", "STATIONEERS_GAME_PORT=27500", "STATIONEERS_QUERY_PORT=27015"],
    binds: ["/opt/stationeers:/steamcmd/stationeers"], ports: { "27500/udp": [{ HostIp: "", HostPort: "27500" }], "27500/tcp": [{ HostIp: "", HostPort: "27500" }] }, files: {}, ...extra,
  });
const V = (over = {}) => defaults("stationeers", over);
const envOf = (g: ReturnType<typeof mk>) => g.containers.get("stationeers")!.env;

test("all four schema fields are mapped (the image has no max-players env var, so none is claimed)", () => {
  const keys = GAME_CONFIG_SCHEMAS.stationeers.fields.map((f) => f.key);
  for (const k of Object.keys(STATIONEERS_SPEC.fields)) assert.ok(keys.includes(k), k);
  assert.deepEqual(keys.filter((k) => !(k in STATIONEERS_SPEC.fields)), []);
});

test("each field is applied by rebuilding the container with the new env; saves volume and ports kept", async () => {
  const cases: [string, string | number, string][] = [
    ["STATIONEERS_SERVER_NAME", "Moonbase-Alpha", "STATIONEERS_SERVER_NAME=Moonbase-Alpha"],
    ["STATIONEERS_WORLD_NAME", "Mars2", "STATIONEERS_WORLD_NAME=Mars2"],
    ["STATIONEERS_SERVER_PASSWORD", "airl0ck", "STATIONEERS_SERVER_PASSWORD=airl0ck"],
    ["STATIONEERS_SERVER_SAVE_INTERVAL", 600, "STATIONEERS_SERVER_SAVE_INTERVAL=600"],
  ];
  for (const [field, value, want] of cases) {
    const g = mk();
    const out = await runFamily(stationeersApplier, g, V({ [field]: value }), [field]);
    assert.equal(out.ok, true, field);
    assert.ok(envOf(g).includes(want), field);
    assert.ok(envOf(g).includes("STATIONEERS_QUERY_PORT=27015"), "other env carried");
    assert.deepEqual(g.containers.get("stationeers")!.binds, ["/opt/stationeers:/steamcmd/stationeers"]);
    assert.equal(out.restarted, true);
    assert.equal(g.st.active, true);
  }
});

test("a new world name tells the customer the old save is kept", async () => {
  const g = mk();
  const out = await runFamily(stationeersApplier, g, V({ STATIONEERS_WORLD_NAME: "NewWorld" }), ["STATIONEERS_WORLD_NAME"]);
  assert.match(out.notes.join(" "), /previous save is still on the server/);
});

test("password never leaks into a note or command; a blank password is applied as open server", async () => {
  const g = mk();
  const out = await runFamily(stationeersApplier, g, V({ STATIONEERS_SERVER_PASSWORD: "S3cret-pass" }), ["STATIONEERS_SERVER_PASSWORD"]);
  assert.ok(noSecretIn(g, out, "S3cret-pass"));
  const g2 = mk();
  g2.containers.get("stationeers")!.env.push("X=1");
  await runFamily(stationeersApplier, g2, V({ STATIONEERS_SERVER_PASSWORD: "" }), ["STATIONEERS_SERVER_PASSWORD"]);
  assert.ok(envOf(g2).includes("STATIONEERS_SERVER_PASSWORD="));
});

test("idempotent: the same values do not recreate anything", async () => {
  const g = mk();
  const out = await runFamily(stationeersApplier, g, V({ STATIONEERS_SERVER_NAME: "Nxeon", STATIONEERS_WORLD_NAME: "Nxeon World".replace(" ", "-") === "x" ? "" : "Nxeon World" }), ["STATIONEERS_SERVER_NAME"]);
  assert.equal(out.ok, true);
  assert.equal(g.st.created, 0);
});

test("a value with a space is refused by the applier too (the image splits it into separate args); nothing changes", async () => {
  const g = mk();
  const out = await runFamily(stationeersApplier, g, V({ STATIONEERS_SERVER_NAME: "My Base" }), ["STATIONEERS_SERVER_NAME"]);
  assert.equal(out.ok, false);
  assert.equal(g.st.created, 0);
});

test("the schema rejects spaces/quotes in name, world and password, and the new default validates", () => {
  assert.equal(validateConfig("stationeers", { STATIONEERS_SERVER_NAME: "My Base" }).ok, false);
  assert.equal(validateConfig("stationeers", { STATIONEERS_WORLD_NAME: 'a"b' }).ok, false);
  assert.equal(validateConfig("stationeers", { STATIONEERS_SERVER_PASSWORD: "a b" }).ok, false);
  assert.equal(validateConfig("stationeers", {}).ok, true);
});

test("rollback: a failed create restores the old container and restarts it", async () => {
  const g = mk({ createFails: true });
  const out = await runFamily(stationeersApplier, g, V({ STATIONEERS_SERVER_NAME: "Other" }), ["STATIONEERS_SERVER_NAME"]);
  assert.equal(out.ok, false);
  assert.ok(envOf(g).includes("STATIONEERS_SERVER_NAME=Nxeon"));
  assert.equal(g.st.active, true);
});

test("a stopped server is rebuilt but not started", async () => {
  const g = mk({ active: false });
  const out = await runFamily(stationeersApplier, g, V({ STATIONEERS_SERVER_NAME: "Quiet" }), ["STATIONEERS_SERVER_NAME"]);
  assert.equal(out.ok, true);
  assert.equal(g.st.active, false);
  assert.match(out.notes.join(" "), /stopped/);
});

test("fresh install: the checkout values reach the setup script through the existing -e placeholders", () => {
  const script = "docker run -d --name stationeers -e STATIONEERS_SERVER_NAME='Nxeon' -e STATIONEERS_WORLD_NAME='Nxeon World' -e STATIONEERS_SERVER_PASSWORD='' -v /opt/stationeers:/steamcmd/stationeers didstopia/stationeers-server:latest";
  const out = applyGameConfigEnv(script, "stationeers", V({ STATIONEERS_SERVER_NAME: "Base", STATIONEERS_SERVER_PASSWORD: "pw" }));
  assert.match(out, /-e STATIONEERS_SERVER_NAME='Base'/);
  assert.match(out, /-e STATIONEERS_SERVER_PASSWORD='pw'/);
});
